          } else if (cmd === "note") {
            const body = readFileSync(a[0], "utf-8"), old = await find(e.TG_PR);
            if (old) await edit(e.TG_PR, old.id, body); else await call("POST", notes(e.TG_PR), { body });
          } else if (cmd === "reply") {
